	/**
	* The CSS class names of the cell that wraps the underlying input control
	*/
	className: PropTypes.string,
	/**
	* Provide a `Slug` component to be rendered inside the `TableSlugRow` component
	*/
	slug: PropTypes.node
};
//#endregion
